def subgroups_z12():
    """Enumerate subgroups of Z/12 and verify product structure {1,2,4} x {1,3}."""
    n = 12
    # subgroup generated by d where d|12: <k> = multiples of gcd(k,12)
    # All subgroups of Z/n are unique per divisor: <n/d> has order d for d|n.
    divisors = [d for d in range(1, n + 1) if n % d == 0]
    subgroups = []
    for d in divisors:
        gen = n // d
        H = sorted({(k * gen) % n for k in range(d)})
        subgroups.append({"order": d, "elements": H, "generator": gen})
    # Expected: orders 1,2,3,4,6,12 — products of {1,2,4} x {1,3}
    sylow2_orders = {1, 2, 4}
    sylow3_orders = {1, 3}
    expected_orders = sorted({a * b for a in sylow2_orders for b in sylow3_orders})
    observed_orders = sorted(s["order"] for s in subgroups)
    # Endomorphisms of Z/12 are multiplication-by-m maps; they preserve Sylow parts
    # because Hom(Z/12,Z/12) ≅ Z/12 and m*(S2 x S3) stays in the primary decomposition.
    endomorphism_checks = []
    for m in range(12):
        # image of 2-Sylow <3> = {0,3,6,9} under *m
        s2 = {0, 3, 6, 9}
        s3 = {0, 4, 8}
        im2 = {(m * x) % 12 for x in s2}
        im3 = {(m * x) % 12 for x in s3}
        # primary decomposition preservation: image of Sylow-2 lands in Sylow-2
        # iff im2 ⊆ s2 (similarly s3). Multiplication maps always send primary
        # components into themselves for abelian groups Z/n.
        endomorphism_checks.append(
            {
                "m": m,
                "im_sylow2_subset": im2 <= s2,
                "im_sylow3_subset": im3 <= s3,
            }
        )
    endo_pass = all(c["im_sylow2_subset"] and c["im_sylow3_subset"] for c in endomorphism_checks)
    return {
        "group": "Z/12",
        "subgroups": subgroups,
        "observed_orders": observed_orders,
        "expected_orders_products_of_sylows": expected_orders,
        "orders_match": observed_orders == expected_orders,
        "endomorphism_preservation_pass": endo_pass,
        "endomorphism_checks": endomorphism_checks,
        "chain": {
            "statement": "E > 2E > 4E = C with quotients Z/2 and Z/4",
            "model": "Z/12 ≅ Z/4 x Z/3; take S=Z/4, C=Z/3 embedded as 4Z/12",
            "C": [0, 4, 8],
            "2E_as_2Z_mod12": [0, 2, 4, 6, 8, 10],
            "4E_as_4Z_mod12": [0, 4, 8],
            "quotients": {"E/2E": "Z/2", "E/4E": "Z/4", "note": "4E=C in this model"},
            "on_C_targets": "both quotients identically 0 (C ⊆ 2E and C = 4E)",
        },
        "pass": observed_orders == expected_orders and endo_pass,
    }


def chain_n19():
    F, E, cell = build_curve("n19_koblitz_h4")
    order_info = verify_order(E, cell)
    # Build chain certificate on the order group Z/(4l)
    l = cell["expected_l"]
    N = 4 * l
    assert N == cell["expected_E"]
    C = list(range(0, N, 4))  # 4Z/(4l) ≅ Z/l
    twoE = list(range(0, N, 2))
    fourE = list(range(0, N, 4))
    # Quotient sizes
    q_E_2E = N // len(twoE)
    q_E_4E = N // len(fourE)
    # Spot-check: random elements of C map to 0 in both quotients
    # (identity on residue: c mod 2 == 0 and c mod 4 == 0)
    c_in_2E = all(c % 2 == 0 for c in C[:20])
    c_eq_4E = fourE == C
    return {
        "cell": cell["curve_id"],
        "field_poly": "t^19+t^5+t^2+t+1",
        "curve": "y^2+xy=x^3+1",
        "order_info": order_info,
        "l_prime_rechecked": is_prime(l),
        "chain": {
            "E_order": N,
            "2E_order": len(twoE),
            "4E_order": len(fourE),
            "C_order": l,
            "4E_equals_C": c_eq_4E,
            "quotients": {"E/2E": f"Z/{q_E_2E}", "E/4E": f"Z/{q_E_4E}"},
            "C_targets_trivial_in_quotients": c_in_2E and c_eq_4E,
            "reading": (
                "Target-side: quotients carry no C-DL information (identically 0 on C). "
                "Leg-side lever owned by DC-04 (IDEA-20260922-1b16d7 / 153a90); not claimed here."
            ),
        },
        "pass": bool(order_info["pass"] and c_eq_4E and q_E_2E == 2 and q_E_4E == 4),
    }


