def methodological_note() -> str:
    return """# Methodological note — EXP-BINSTD-58758f Stage 0 (HOLD-O)

Task: `TASK-20261001-c04c94`. Observations / certificates only. No deployed-curve
break claim. No free-cofactor framing.

## Target-side reading (closed)

The HOLD-O correction replaces the false step "quotients of S are trivial or
all of S" by the chain

```text
E > 2E > 4E = C
```

with quotients `E/2E ≅ Z/2` (parity map `π = Tr(x)+Tr(a)`) and `E/4E ≅ Z/4`.
Both quotients are identically 0 on C-targets, so they carry **no** information
about a C-target discrete log. Target-side "spend the cofactor via a group
quotient" therefore closes to the same C-reduction rho already performs
(Theorem-C style prime-order rigidity on C). Hand-checked on `Z/12` and on the
n=19 Koblitz order group `Z/(4·130873)`.

## Leg-side lever (out of scope — DC-04)

The same chain is nontrivial on legs. Parity alignment and the nonlinear E/4E
bit as window conditions are owned by the DC-04 cluster:

- `IDEA-20260922-1b16d7`
- `IDEA-20260922-153a90`

This experiment cross-cites those records and does **not** redesign or claim
that lever.

## Part (B) pricing: base-size, not free

Whether builders restrict candidate x-coordinates to one cofactor coset
(`H_unspent`) or admit all cosets (`H_spent`) is an engineering code/spec read
(Stage 0 builder audit). If unrestricted windows are larger, yield conservation
prices the effect as ordinary factor-base **size**:

```text
V / V_C  ~  4^{m-1}
```

at about 4× the unknowns — the standard base-size trade. The protocol forbids
calling this a free structural / free cofactor gain.

## Null controls (h=1 impossible)

No ordinary binary Weierstrass curve `y²+xy=x³+a x²+b` has odd order (rational
2-torsion `(0,√b)` always exists). The h=1 null is forbidden. Controls are:

1. h=2 sibling (Z/4 undefined; parity ratio still ~2) — Stage 2;
2. relabelled `Z/(4l)` generic group — Stage 1 replica.

## ECC2K-130

Named structural setting only. No scientific group walk at deployed m≥131.
"""


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--run-id", required=True)
    args = ap.parse_args()
    started = utc_now()
    t0 = time.time()
    logs = []

    z12 = subgroups_z12()
    logs.append(f"Z/12 pass={z12['pass']} orders={z12['observed_orders']}")
    n19 = chain_n19()
    logs.append(
        f"n19 pass={n19['pass']} order={n19['order_info']['group_order_E_measured']} "
        f"l_prime={n19['l_prime_rechecked']}"
    )
    chain = {
        "experiment_id": "EXP-BINSTD-58758f",
        "task_id": "TASK-20261001-c04c94",
        "hold_o": True,
        "certificate_kind_note": "measurement/symbolic chain check; certificate.kind=none on run",
        "Z12": z12,
        "n19_koblitz": n19,
        "pass": bool(z12["pass"] and n19["pass"]),
        "halt_on_failure": True,
    }
    if not chain["pass"]:
        raise SystemExit("HARD HALT: chain certificate failed")

    audit = builder_audit_table()
    note = methodological_note()

    stage0 = EXP_ROOT / "stage0"
    dump_yaml(stage0 / "chain-certificate.yaml", chain)
    dump_yaml(stage0 / "builder-audit-table.yaml", audit)
    dump_text(stage0 / "methodological-note.md", note)
    logs.append("wrote stage0/chain-certificate.yaml, builder-audit-table.yaml, methodological-note.md")
    logs.append(f"builder rows: {[r['builder']+':'+r['label'] for r in audit['rows']]}")

    finished = utc_now()
    wall = time.time() - t0
    stdout = "\n".join(logs) + "\n"
    write_run_package(
        args.run_id,
        stage=0,
        arm="chain+builder-audit",
        seed=None,
        command=f"python3 experiments/EXP-BINSTD-58758f/implementation/stage0_run.py --run-id {args.run_id}",
        parameters={"arms": ["Z12", "n19_koblitz", "builder_audit"]},
        metrics={
            "chain_certificate_pass": True,
            "builder_rows": len(audit["rows"]),
            "n_H_spent": audit["summary"]["n_H_spent"],
            "n_H_unspent": audit["summary"]["n_H_unspent"],
            "h1_null_absent": True,
        },
        valid=True,
        invalid_reason=None,
        termination_reason="completed",
        stdout_text=stdout,
        started_at=started,
        finished_at=finished,
        wall_seconds=wall,
        certificate_note=(
            "Stage 0 symbolic/arithmetic chain + code/spec builder audit; "
            "not a discrete_log/decomposition/key_recovery claim"
        ),
    )
    print(stdout)


if __name__ == "__main__":
    main()
